import XCTest

final class UITestTests: XCTestCase {
    func testDumpHierarchy() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()
        Thread.sleep(forTimeInterval: 4)
        let dump = app.debugDescription
        try? dump.write(toFile: "/tmp/uitest_hierarchy.txt", atomically: true, encoding: .utf8)
        print("HIERARCHY_START")
        print(dump)
        print("HIERARCHY_END")
    }
}

import XCTest

final class UITestTests: XCTestCase {
    func testNavigateToSessions() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()
        Thread.sleep(forTimeInterval: 3)

        func dump(_ tag: String) {
            print("DUMP_\(tag)_START")
            print(app.debugDescription)
            print("DUMP_\(tag)_END")
        }

        func tapFirst(_ tag: String, _ elements: [XCUIElement]) -> Bool {
            for e in elements {
                if e.waitForExistence(timeout: 3) {
                    e.tap()
                    print("TAPPED_\(tag)")
                    return true
                }
            }
            print("NOT_FOUND_\(tag)")
            return false
        }

        let userMenu = app.buttons["User menu"]
        XCTAssertTrue(userMenu.waitForExistence(timeout: 5), "user menu button missing")
        userMenu.tap()
        print("TAPPED_USER_MENU")
        Thread.sleep(forTimeInterval: 2)
        dump("SIDE_MENU")

        _ = tapFirst("SETTINGS", [
            app.buttons["Settings"],
            app.cells["Settings"],
            app.staticTexts["Settings"],
        ])
        Thread.sleep(forTimeInterval: 2)
        dump("SETTINGS_SCREEN")

        _ = tapFirst("SESSIONS", [
            app.cells["Sessions"],
            app.buttons["Sessions"],
            app.staticTexts["Sessions"],
        ])
        Thread.sleep(forTimeInterval: 2)
        dump("SESSIONS_SCREEN")
    }
}

